<?php
namespace Tests\Feature;
use Tests\TestCase; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Http; use App\Models\{Order,Show,Venue,Event,Organization,Payment}; use App\Services\ZarinpalService;
class PaymentFlowTest extends TestCase {use RefreshDatabase; public function test_zarinpal_request_and_verify_are_recorded():void{$org=Organization::create(['name'=>'Test','slug'=>'test']);$venue=Venue::create(['organization_id'=>$org->id,'name'=>'A','city'=>'تهران','capacity'=>1]);$event=Event::create(['organization_id'=>$org->id,'title'=>'Test','slug'=>'test-event','type'=>'cinema','status'=>'published']);$show=Show::create(['event_id'=>$event->id,'venue_id'=>$venue->id,'starts_at'=>now()->addHour(),'price'=>10000]);$order=Order::create(['show_id'=>$show->id,'code'=>'T-1','total'=>10000,'status'=>'pending']);Http::fake([ '*' => Http::response(['data'=>['code'=>100,'authority'=>'A123'],'errors'=>[]],200)]);$service=app(ZarinpalService::class);$payment=$service->request($order);$this->assertSame('A123',$payment->authority);$this->assertTrue($service->verify($payment));$this->assertSame('paid',$payment->fresh()->status);}}
